import java.io.IOException;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class XSSFixedServlet extends HttpServlet {

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("userInput");

        // Validate user input to prevent script injection
        if (userInput != null && !userInput.isEmpty()) {
            userInput = userInput.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
        } else {
            userInput = "Guest"; // Provide a default value if user input is empty
        }

        String output = "<h1>Welcome, " + userInput + "!</h1>";

        response.setContentType("text/html");
        response.getWriter().println(output);
    }
}

