import java.util.Scanner;

public class SecureBufferHandling {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String userInput = scanner.nextLine();

        int bufferSize = 10;
        char[] buffer = new char[bufferSize];

        // Copy user input into buffer with proper bounds checking
        int length = Math.min(userInput.length(), bufferSize);
        userInput.getChars(0, length, buffer, 0);

        System.out.println("Buffer content: " + new String(buffer));
    }
}

