        String safeUserInput = encodeUserInput(userInput);
        response.getWriter().println("<h1>Your input: " + safeUserInput + "</h1>");
    }

    private String encodeUserInput(String userInput) {
        return org.owasp.esapi.ESAPI.encoder().encodeForHTML(userInput);
    }
