import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class XSSFixedServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");

        // Properly sanitize and encode user input before outputting it
        String sanitizedInput = escapeHtml(userInput);

        PrintWriter out = response.getWriter();
        out.println("<html>");
        out.println("<head><title>XSS Fixed Page</title></head>");
        out.println("<body>");
        out.println("User Input: " + sanitizedInput);
        out.println("</body>");
        out.println("</html>");
    }

    // Helper method to escape HTML characters to prevent XSS
    private String escapeHtml(String input) {
        return input
                .replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#39;");
    }
}

