import java.io.*;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.Scanner;
import javax.servlet.*;
import javax.servlet.http.*;
import org.owasp.encoder.Encode;

public class CombinedAuditService_1667 {

public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Enter file name: ");
        String fileName = scanner.nextLine();

        // Ensure that fileName does not contain any path traversal sequences
        if (!fileName.contains("..")) {
            try {
                File file = new File("/path/to/files/" + fileName);
                if (file.exists() && file.isFile()) {
                    byte[] fileContent = Files.readAllBytes(file.toPath());
                    System.out.println("File content: " + new String(fileContent));
                } else {
                    System.out.println("File not found.");
                }
            } catch (IOException e) {
                System.out.println("An error occurred.");
                e.printStackTrace();
            }
        } else {
            System.out.println("Invalid file name.");
        }
    }

protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");

        // Properly encoding user input to prevent XSS
        String encodedUserInput = Encode.forHtml(userInput);

        PrintWriter out = response.getWriter();
        out.println("<html>");
        out.println("<body>");
        out.println("<h1>User Input: " + encodedUserInput + "</h1>"); // Safe code
        out.println("</body>");
        out.println("</html>");
    }
