public class SecureBufferExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String name = scanner.nextLine().trim(); // Read a full line and remove leading/trailing whitespaces

        // Limit the length of input to prevent buffer overflow
        if (name.length() > 10) {
            System.out.println("Input is too long. Please enter a name with at most 10 characters.");
            return;
        }

        char[] buffer = new char[10];
        name.getChars(0, name.length(), buffer, 0);

        System.out.println("Hello, " + String.valueOf(buffer));
