import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class CombinedAuditService_1281 {

public void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");
        PrintWriter out = response.getWriter();

        out.println("<html>");
        out.println("<body>");
        out.println("<h1>Welcome, " + escapeHtml(userInput) + "!</h1>");
        out.println("</body>");
        out.println("</html>");
    }

    private String escapeHtml(String input) {
        if (input == null) {
            return "";
        }
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&#39;");
    }

public static void main(String[] args) {
        String userInput = "../secretFile.txt";
        String directory = "/var/www/data/";

        if (!isInputValid(userInput)) {
            System.out.println("Invalid input path");
            return;
        }

        File file = new File(directory + userInput);

        try {
            FileInputStream fis = new FileInputStream(file);
            int content;
            while ((content = fis.read()) != -1) {
                System.out.print((char) content);
            }
            fis.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static boolean isInputValid(String userInput) {
        // Check if the userInput contains any directory traversal characters
        if (userInput.contains("..") || userInput.contains("/") || userInput.contains("\\")) {
            return false;
        }
        return true;
    }
