import java.util.Scanner;

public class SafeBufferHandling {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Enter a string:");
        String input = scanner.nextLine();

        // Limit the buffer size to prevent buffer overflow
        int bufferSize = Math.min(input.length(), 10);
        char[] buffer = new char[bufferSize];

        // Copy user input into buffer with bounds checking
        for (int i = 0; i < bufferSize; i++) {
            buffer[i] = input.charAt(i);
        }

        System.out.println("Buffer content: " + new String(buffer));
    }
}

