import javax.servlet.http.*;

public class XSSFixedServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String userInput = request.getParameter("input");

        // Properly encode user input to prevent XSS
        String safeUserInput = encodeForHTML(userInput);

        PrintWriter out = response.getWriter();
        out.println("<html>");
        out.println("<head><title>Secure Page</title></head>");
        out.println("<body>");
        out.println("<h1>User Input:</h1>");
        out.println(safeUserInput);
        out.println("</body>");
        out.println("</html>");
    }

    private String encodeForHTML(String input) {
        // Implement proper HTML encoding here
        return input.replaceAll("&", "&amp;")
                    .replaceAll("<", "&lt;")
                    .replaceAll(">", "&gt;")
                    .replaceAll("\"", "&quot;")
                    .replaceAll("'", "&#39;");
    }
}

