    private String sanitizeUserInput(String input) {
        // Replace characters that have special meaning in HTML with their respective HTML entities
        input = input.replaceAll("&", "&amp;")
                     .replaceAll("<", "&lt;")
                     .replaceAll(">", "&gt;")
                     .replaceAll("\"", "&quot;")
                     .replaceAll("'", "&#39;");

        return input;
    }
}

