import java.util.Scanner;

public class SecureBufferExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your name: ");
        String name = scanner.nextLine();

        // Validate input length to prevent buffer overflow
        if (name.length() > 10) {
            System.out.println("Input exceeds maximum length. Please enter a shorter name.");
            return;
        }

        char[] buffer = new char[10];
        // Copy input to buffer safely
        name.getChars(0, Math.min(name.length(), buffer.length), buffer, 0);

        System.out.println("Hello, " + String.valueOf(buffer).trim()); // Trim any trailing null characters
    }
}

