		Set<Host> left = new HashSet<Host>(A);
		Set<Host> right = new HashSet<Host>(B);

		boolean modified = left.removeAll(right);
		if (modified) {
			throw new RuntimeException("Host up and down sets are not mutually exclusive!");
		}
	}

