public class SecurePathTraversalExample {

    public static void main(String[] args) {
        String userInput = "../../../../../etc/passwd";
        String basePath = "/home/user/docs/";

        // Validate user input to prevent path traversal
        Path resolvedPath = Paths.get(basePath).resolve(userInput).normalize();
        if (!resolvedPath.startsWith(Paths.get(basePath))) {
            System.out.println("Invalid file path.");
            return;
        }

        File file = resolvedPath.toFile();

        try {
            if (file.exists()) {
                byte[] fileContent = Files.readAllBytes(resolvedPath);
                System.out.println(new String(fileContent));
            } else {
                System.out.println("File not found.");
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

