protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String userInput = request.getParameter("input");
        PrintWriter out = response.getWriter();

        out.println("<html>");
        out.println("<head><title>Secure Code Example</title></head>");
        out.println("<body>");

        // Properly encoding user input to prevent XSS
        out.println("<p>User Input: " + encodeHTML(userInput) + "</p>");

        out.println("</body>");
        out.println("</html>");
    }

    private String encodeHTML(String input) {
        return input.replace("&", "&amp;")
                    .replace("\"", "&quot;")
                    .replace("'", "&#39;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;");
    }

public static void main(String[] args) {
        String userInput = "../secretFile.txt";
        String directory = "/var/www/files/";

        // Validate user input to prevent path traversal
        if (!Paths.get(userInput).normalize().toString().equals(userInput)) {
            System.err.println("Invalid file path.");
