import javax.servlet.*;
import javax.servlet.http.*;

public class CombinedAuditService_250 {

protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String userInput = request.getParameter("input");

        PrintWriter out = response.getWriter();
        out.println("<html><body>");
        out.println("<h1>Welcome to our website!</h1>");
        out.println("<p>You entered: " + sanitizeInput(userInput) + "</p>"); // Sanitize user input before outputting
        out.println("</body></html>");
    }

    private String sanitizeInput(String input) {
        return input == null ? "" : input.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
    }

public static void main(String[] args) {
        try {
            String userInput = "serializedObject"; // Assume this is user-provided input
