public class SecurePathTraversal {

    private static final String BASE_DIRECTORY = "/path/to/directory/";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter file name: ");
        String fileName = scanner.nextLine();

        File file = new File(BASE_DIRECTORY + fileName);

        if (file.toPath().normalize().startsWith(Paths.get(BASE_DIRECTORY).normalize())) {
            try {
                byte[] content = Files.readAllBytes(file.toPath());
                System.out.println(new String(content));
            } catch (IOException e) {
                System.out.println("Error reading file: " + e.getMessage());
            }
        } else {
            System.out.println("Access to files outside the directory is not allowed.");
        }
    }
}

