        response.getWriter().write(output);
    }

    private String sanitizeInput(String input) {
        if (input == null) {
            return "";
        }
        // Replace characters that are significant in HTML with their respective HTML entities
        return input.replaceAll("&", "&amp;")
                    .replaceAll("<", "&lt;")
                    .replaceAll(">", "&gt;")
                    .replaceAll("\"", "&quot;")
                    .replaceAll("'", "&#x27;");
    }
}

