public class SecureServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String userInput = request.getParameter("input");
        PrintWriter out = response.getWriter();

        out.println("<html>");
        out.println("<head><title>Secure Code Example</title></head>");
        out.println("<body>");

        // Sanitize and encode user input before displaying
        out.println("User input: " + encodeHTML(userInput));

        out.println("</body>");
        out.println("</html>");
    }

    private String encodeHTML(String input) {
        if (input == null) {
            return "";
        }

        // Replace characters that have special meaning in HTML with their corresponding HTML entities
        return input.replaceAll("&", "&amp;")
                    .replaceAll("<", "&lt;")
                    .replaceAll(">", "&gt;")
                    .replaceAll("\"", "&quot;")
                    .replaceAll("'", "&#39;");
    }
}

