        // DARK WARM
        float[] scales = new float[] { 2.2f, 2.0f, 1.55f};
        float[] offsets = new float[] {-20.0f, -90.0f, -110.0f};

        // BRIGHT NATURAL
//        float[] scales = new float[] { 1.1f, .9f, .7f};
